import{_ as t,a as o,b as a,c as i,d as n,e as r}from"./chunks/c92378f4665bfa38d5bb.D5F0CFGw.js";import{_ as s,o as l,c as h,a5 as p}from"./chunks/framework.DNkHA0lr.js";const k=JSON.parse('{"title":"How To Actually Make $1 Million With AI","description":"","frontmatter":{"title":"How To Actually Make $1 Million With AI","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/how-to-actually-make-1-million-with-ai.md","filePath":"en/letters/how-to-actually-make-1-million-with-ai.md"}'),d={name:"en/letters/how-to-actually-make-1-million-with-ai.md"};function u(c,e,m,y,f,g){return l(),h("div",null,[...e[0]||(e[0]=[p('<h1 id="how-to-actually-make-1-million-with-ai" tabindex="-1">How To Actually Make $1 Million With AI <a class="header-anchor" href="#how-to-actually-make-1-million-with-ai" aria-label="Permalink to &quot;How To Actually Make $1 Million With AI&quot;">​</a></h1><p>Dan Koe · 2025-04-06 · <a href="https://thedankoe.com/letters/how-to-actually-make-1-million-with-ai/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/how-to-actually-make-1-million-with-ai">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/z9dtU-xUX04?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>I bet you clicked on this so you could find a quick way to make money.</p><p>I hate to break it to you, but you will never live in a world where that is possible.</p><p>There will never ever ever be a time where you can just tell a bunch of robots to go and make you money so you can sit around with the poor habits you don’t want to change and do nothing.</p><p>Not how it works.</p><p>The reality is that AI hasn’t changed a thing.</p><ul><li>You still need traffic</li><li>You still need content</li><li>You still need promotions</li><li>You still need a valuable offer</li><li>You still need a customer avatar</li><li>You still need a landing page</li><li>You still need copywriting</li></ul><p>And of course, you still need to <em>understand</em> what you’re doing to orchestrate all of those things well.</p><p>So no. This isn’t some fancy new AI business model that absolves you from learning every principle of business.</p><p>The only thing that AI has changed is the speed and quality which you can do the things above.</p><p>But here’s the cool part:</p><p>I enjoy writing content and books (like my new little book <a href="https://thedankoe.com/purpose" target="_blank" rel="noreferrer">Purpose &amp; Profit</a> which is free as a PDF that you can chat with in Kortex now! (Drag the PDF into a chat or your library)). That’s what I want to spend my time doing. That’s my differentiator—my ideas and novel perspectives.</p><p>I do not, however, enjoy marketing. I’m good at it if I take the required amount of time to prime creativity, but it’s a drag to get myself to actually care about optimizing headlines and leads and offer positioning and all of that stuff. I’d rather spend my finite creative firepower on the writing I enjoy doing.</p><p>In business, when you don’t enjoy doing something, it’s wise to outsource it to someone—or now, something—that can do it better.</p><p>The thing is, AI is not a good marketer (or writer) out of the box. AI has a swath of general information that needs to be made specific.</p><p>So, if you want to outsource your marketing, you have 2 options:</p><ol><li>Become very good at marketing and create your own AI system.</li><li>Find someone who is good at marketing, understand the process, and use their system so you can focus on what you enjoy doing.</li></ol><p>With that I say you’re in luck!</p><p>Because I’ve created an AI system that can create better customer avatars, offers, landing pages, and sales copy than 99% of creators, businesses, and especially corporate marketing departments.</p><h3 id="how-to-make-1-million-in-general" tabindex="-1">How To Make $1 Million (In General) <a class="header-anchor" href="#how-to-make-1-million-in-general" aria-label="Permalink to &quot;How To Make $1 Million (In General)&quot;">​</a></h3><p>Before we start, let’s break down a few realistic paths to get to $1 million a year.</p><p>$1,000,000 / 12 = $83,333 per month</p><p>$83,333 / 30 = $2,777 per day</p><p>Now, there are a few ways to do that.</p><ul><li>Sell 18 $150 products a day</li><li>Sell 111 $25 subscriptions a day</li><li>Land one $5000 client every other day</li><li>Land one $10,000 client every 4 days</li><li>A combination of both. 1-2 clients a week and a few product sales a day.</li><li>Or whatever other combination and price point there is to hit $1 million.</li></ul><p>If you go the client route, you will probably need a team after a certain amount of time (or have the service so productized you can handle fulfillment yourself).</p><p>If you go the product route or subscription route, like a software or membership, you will need a lot of traffic.</p><p>How do you get enough traffic to make that many product or service sales?</p><p>At a 2.5% conversion rate on a landing page that allows people to purchase your product, you need 720 people to visit that page a day to make 18 sales on a $150 product.</p><p>Where do those 720 people come from?</p><p>Social media, ads, SEO, or some other form of influencer marketing or word of mouth.</p><p>So, if we assume you’re skilled at social media (yes, social media is a skill, not luck based on an algorithm), you can:</p><ul><li>Get 10-50,000 views per YouTube video</li><li>Get 500k to 1 million impressions on social media per month</li></ul><p>That means out of that many people, you need only 720 people to click on your landing page in order to make $1 million a year.</p><p><em>720 people out of hundreds of thousands isn’t that much to ask for.</em></p><p><em>And of course, most people would be happy with much less than $1 million per year.</em></p><p>For those who aren’t used to that kind of money or work based on salary, it is a bit “out there” to think it can be that simple. That’s what your employer does to make multiples on top of what they pay you to execute one specific part of the process that makes them money.</p><p>But of course, it’s simple not easy yada yada I get it.</p><p>It can take 5-10 years to get <em>really</em> good at offer creation, social media marketing, and copywriting.</p><p>But if we train AI on the principles of them all, and feed them data from legendary marketers, you’d be shocked how well AI can do those things for you.</p><h2 id="how-to-use-ai-to-make-1-million" tabindex="-1">How To Use AI To Make $1 Million <a class="header-anchor" href="#how-to-use-ai-to-make-1-million" aria-label="Permalink to &quot;How To Use AI To Make $1 Million&quot;">​</a></h2><p>If you haven’t already, <a href="/letters/learn-ai-to-10x-any-other-skill-full-beginner-guide">read my previous letter that goes over the absolute basics of AI</a> and how to write meta prompts.</p><p>You can read it after this to fill in the blanks.</p><p>For now, I’m going to teach you everything you need to know about branding, marketing, and content along with a way to have AI do it for you.</p><h3 id="personal-brand-strategy" tabindex="-1">Personal Brand Strategy <a class="header-anchor" href="#personal-brand-strategy" aria-label="Permalink to &quot;Personal Brand Strategy&quot;">​</a></h3><p>We’re going to focus on social media because:</p><ol><li>It’s free, and frankly, I don’t understand paid ads enough to teach you (and testing content on social media is how you create winning ads without blowing a ton of money)</li><li>You probably don’t have the time for SEO, or the money for sponsoring influencers (again, use socials to test)</li><li>Even though social media is free and accessible, it’s arguably the best source of traffic, and an audience = leverage</li></ol><p>So here’s what you need to do:</p><p>First, go to <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex and start a new chat</a> with the Personal Brand Strategy option under the ‘Market’ category.</p><p><img src="'+t+'" alt=""></p><p>Hit ‘enter’ to start the interview.</p><p>Then, it will walk you through a series of questions and eventually spit out an entire strategy with:</p><ul><li>A summary of your transformation story, ideal target audience, and value proposition</li><li>Your ‘domain of mastery’ composed of one monetizable skill/interest followed by two complementary skills/interests</li><li>A list of your audience’s pain points, content inspiration sources, and authority building topics</li><li>A condensed and expanded social media bio to use across different platforms</li><li>A monetization strategy with potential services to offer, products to sell, and starting points</li><li>A content strategy with posting dates and general tips</li></ul><p><img src="'+o+'" alt=""></p><p>I personally made all of these AI flows in Kortex based off of my own courses, experience, and industry best practices.</p><p>They’re a very good starting point.</p><p>Copy the output of this prompt and save it as a new document so you can keep it safe.</p><h3 id="customer-avatar" tabindex="-1">Customer Avatar <a class="header-anchor" href="#customer-avatar" aria-label="Permalink to &quot;Customer Avatar&quot;">​</a></h3><p>Market research is annoying.</p><p>I’ve always hated doing it, and because of that, my customer avatars were always half-assed.</p><p>I never felt like I <em>dug deep</em> into who they were, and the rest of my marketing suffered because of that.</p><p>With your strategy from above, we need to dig deeper into your target audience.</p><p>We need to understand their demographics, psychographics, buying behavior, where they hang out online, and more.</p><p>For this step, go to the ‘Customer Avatar Generator’ inside the same ‘Market’ category when creating a new prompt.</p><p>Fill in the blanks with the target audience description you got from your Personal Brand Strategy.</p><p><img src="'+a+'" alt=""></p><p>Answer all of the interview questions from the AI, save your customer avatar to a new document, and be ready to reference it in everything else you do from now on.</p><h3 id="irresistible-offer" tabindex="-1">Irresistible Offer <a class="header-anchor" href="#irresistible-offer" aria-label="Permalink to &quot;Irresistible Offer&quot;">​</a></h3><p>Here’s the main problems at this step:</p><ul><li>Most people don’t know what they want to sell in order to monetize</li><li>If people do know what they want to sell, it usually sucks because it’s vague</li><li>When they try to create a more compelling offer, it’s usually based on guesswork rather than data and people aren’t confident in what they’re selling</li></ul><p>The cool thing about AI is that it has literally the entire internet’s worth of knowledge, and certain models like Claude don’t suffer from self-doubt and a lack of confidence that impacts the quality of their work.</p><p>So, do the same thing this time.</p><p>Go to the ‘Irresistible Offer Creation Blueprint’, fill in the first blank with “@customer avatar document” and the second blank with a brief description of the product or service you want to sell based on your brand strategy (or based on one you already have planned).</p><p>Again, answer the clarifying questions and kAI will spit out a full offer with:</p><ul><li>The delivery mechanism (course, template, freelancing, etc)</li><li>The big idea to capture attention</li><li>The big problem and amplifying pain points</li><li>The quantifiable outcome that your audience desires</li><li>The unique mechanism that sets your offer apart</li><li>General features and benefits (you can and should change these)</li><li>The value equation analysis from Alex Hormozi</li><li>General positioning recommendations to make it even better</li></ul><p><img src="'+i+'" alt=""></p><p>Again, save this as a document in your workspace for the next step.</p><h3 id="high-converting-landing-page" tabindex="-1">High Converting Landing Page <a class="header-anchor" href="#high-converting-landing-page" aria-label="Permalink to &quot;High Converting Landing Page&quot;">​</a></h3><p>Now you have all of your marketing firepower saved inside documents in your workspace.</p><p>We need kAI to string all of that together into a well-written persuasive landing page.</p><p>I wouldn’t worry about landing page design just now. In fact, the highest converting landing pages are often pure and persuasive text.</p><p>You can take the output that kAI gives you, create the product on <a href="https://join.stan.store/thedankoe" target="_blank" rel="noreferrer">Stan (a place for creators to host products – and the most affordable, feature rich option)</a>, and paste your landing page text into there.</p><p>After testing this, the writing that kAI spits out is better than almost any creator I’ve seen. Most creators don’t even think about learning marketing or copywriting, so this alone will get you better results than them (I know because I’ve been doing this for 5 years and have launched over 10 products.)</p><p>We are our own worst enemies when we first get into marketing and copywriting. We overcomplicate things and try to think of the most clever or creative thing and end up with something that falls flat and doesn’t make any money.</p><p>So again, go to the ‘Persuasive Landing Page Generation’ option, insert your target audience, offer blueprint, and optional voice analysis.</p><p>Watch the AI spit out headline variations followed by a structured and persuasive landing page.</p><p>You can see it’s pulling from my voice analysis here, which may not be optimal talking in a philosophical tone, but the rest of the landing page is quite good.</p><p><img src="'+n+'" alt=""></p><p>Make edits as you need, but most of it should be good to go.</p><p>Note: Just because you can spit out copywriting doesn’t mean that you can ignore the need to <em>test.</em> If you don’t make money the first time around, it’s not the AI’s fault. It’s still your fault for not being able to use feedback and iterate.</p><p>You can return to the Landing Page AI chat you have at any time and tell it things like:</p><p>“This isn’t converting well, can you help me understand why?”</p><p>“What can I add to my offer to make it more compelling?”</p><p>“Regenerate 10 headline variations, short and long, so I can test them.”</p><p>Remember that the best way to use AI is to converse with it, not expect it to spit out something perfect on the first go.</p><h3 id="posts-yt-videos-emails-reels" tabindex="-1">Posts, YT Videos, Emails, Reels <a class="header-anchor" href="#posts-yt-videos-emails-reels" aria-label="Permalink to &quot;Posts, YT Videos, Emails, Reels&quot;">​</a></h3><p>You now have a strategy, target audience, offer blueprint, and landing page.</p><p>Now, all you need to do is build the actual product and start posting to social media.</p><p>Thankfully, under the ‘Create’ category there are options to:</p><ul><li>Generate 50+ viral content ideas</li><li>Recreate any viral youtube video in your voice (this is under the default category, deselect any category to see it)</li><li>Write social posts or short video scripts for X, LinkedIn, Threads, IG, YT shorts, or TikTok</li><li>Write threads with better hooks than most creators</li><li>Write YouTube scripts, newsletters, or articles</li><li>Turn an idea into a reel, tiktok, or short</li></ul><p><img src="'+r+'" alt=""></p><p>On top of that, there’s a ‘Persuasive Ads, Emails, &amp; Scripts’ option under the ‘Market’ category that can write sales posts, emails, and ads at varying lengths. It’s decent at writing captions for Instagram and LinkedIn posts that plug your offer.</p><p>The only thing stopping you now is the discipline to sit down and actually do it.</p><p>And if you struggle with that, maybe you need to try the ‘Personal Growth Advisor’ option under the ‘Growth’ category.</p><p>So yeah… all of that’s pretty insane.</p><p>If you want to try them all out, sign up for <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex here.</a></p><p>If you want to create reels or tutorials around Kortex and become an affiliate, <a href="https://kortex.co/affiliates" target="_blank" rel="noreferrer">you can do that here.</a></p><p>Have fun with this, and enjoy the new models (like Llama Scout and Maverick, Gemini 2.5 pro, and all other frontier models). That way you don’t have to pay for multiple subscriptions unless you use AI for images, which we will also be adding at some point.</p><p>If you download the desktop version of kortex and press Ctrl or Command+A, it will open a floating chats window so you can chat with AI at anytime from anywhere on your computer.</p><p>– Dan</p>',112)])])}const v=s(d,[["render",u]]);export{k as __pageData,v as default};
